"""Verify raw DOS writer operands, stale local and external error-call ABI."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'analysis/tools/python'))
from capstone import Cs,CS_ARCH_X86,CS_MODE_16

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--output',type=Path,required=True);args=parser.parse_args();output=args.output.resolve();assert not output.exists() and output.is_relative_to(ROOT/'docs/recovery/evidence');image=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(image).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4';reference_path='docs/recovery/evidence/msdos-api-reference-v1.json';reference=json.loads((ROOT/reference_path).read_text());source=(ROOT/reference['private_path']).read_bytes();assert hashlib.sha256(source).hexdigest()==reference['sha256'];codes={'CREAT':60,'CLOSE':62,'WRITE':64}
    for name,value in codes.items():assert int(re.search(rb'^'+name.encode()+rb' +EQU (\d+)',source,re.MULTILINE).group(1))==value
    md=Cs(CS_ARCH_X86,CS_MODE_16);expected={0x786c:'mov word ptr [bp - 0xa], 0',0x787a:'mov word ptr [bp - 0xa], 1',0x787f:'sub sp, 4',0x7887:'mov ah, 0x3c',0x7889:'int 0x21',0x788b:'jb 0x78d2',0x788d:'mov word ptr [bp - 8], ax',0x789c:'mov cx, 0x4000',0x789f:'mov ax, word ptr [bp + 0xc]',0x78a2:'sub word ptr [bp + 0xc], cx',0x78a5:'sbb word ptr [bp + 0xe], 0',0x78a9:'jae 0x78bc',0x78b8:'add cx, 0x4000',0x78bc:'mov ds, word ptr [bp + 0xa]',0x78bf:'mov dx, word ptr [bp + 8]',0x78c2:'mov bx, word ptr [bp - 8]',0x78c5:'mov ah, 0x40',0x78c7:'int 0x21',0x78c9:'jb 0x78d2',0x78cb:'add word ptr [bp + 0xa], 0x400',0x78d2:'cmp word ptr [bp - 0xa], 0',0x78d6:'jne 0x78e7',0x78d8:'mov ax, 0x6808',0x78db:'mov ds, word ptr [bp - 2]',0x78de:'push word ptr [bp + 6]',0x78e1:'push ax',0x78e2:'lcall 0x16a7, 2',0x78e7:'mov bx, word ptr [bp - 8]',0x78ea:'mov ah, 0x3e',0x78ec:'int 0x21',0x78ee:'xor ax, ax',0x78f0:'add sp, 4'};observations=[]
    for ip,text in expected.items():
        at=0x6c90+ip;i=next(md.disasm(image[at:at+15],ip,count=1));assert i.mnemonic+' '+i.op_str==text;observations.append({'site':f'06C9:{ip:04X}','instruction':text})
    graph_path='analysis/flow/indirect-v8/direct-flow.json';g=json.loads((ROOT/graph_path).read_text());targets={'06C9:7866','06C9:7874'};callers=[{'owner':f['entry'],**c} for f in g['functions'] for c in f['calls'] if c['target'] in targets];record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'instruction_observations':observations,'direct_caller_candidates':callers,'flow_ledger':graph_path,'flow_ledger_sha256':hashlib.sha256((ROOT/graph_path).read_bytes()).hexdigest(),'api_reference':{'path':reference_path,'sha256':hashlib.sha256((ROOT/reference_path).read_bytes()).hexdigest(),'source_path':reference['private_path'],'source_sha256':reference['sha256'],'service_identifiers':codes,'url':reference['url'],'relevant_line_ranges':[[1613,1617]]},'facts':['Policyword writtenatSSBP-A beforeSPallocation; handleSSBP-8 isinitializedonlyafterCREATEsuccess. Optionalcreateerror stillclosesstaleseededhandle.','Lengthlow/highwords decrementedbeforewrite withSUB/SBB; tailcountrecoveredafterborrow. Segment+400aftereveryCFclearwrite, returnedAXshortcount notcompared.','CloseCFignored, AX0/ADDSP4/plainfarRETF4; savedDIthenSIthenDSthenBP restoredfromactualSS.','Errorpolicy0 preparesnearfilename/format6808 underrestoredDS, thenfarCALL16A7:0002; preparedtwo words do notestablishcalleeformalarity/sourcevariadics.','FN348errorcalleecontractstillpending. Syntacticreturn/fallthrough andcleanup/formatter/exitcalls areunresolvedintegration, notno-return ornormalreturn proof.'], 'limits':'Staticinstruction/historicalDOSidentity/callerinventory only. NoactualDOS/file writes, interruptframes/IRQ, resourceformat, fullstate/core/device/game/fidelity admission. Rawerrorcallboundary retaineduntilcalleecontract closes; actualsourceproducer/capacity/lifetime andP2/P3 resourcefedchecks separate.'};output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','sites':len(observations),'callers':len(callers)}))

if __name__=='__main__':main()
